#: Codenames this app adds to the global catalog (catalog.view/manage came
#: with feat(catalog); the accounts seed predates them).
_CATALOG_CODES = ("catalog.view", "catalog.manage")


def seed_catalog_permissions(apps: "Apps", schema_editor: "BaseDatabaseSchemaEditor") -> None:
    """Insert the catalog permission codenames (idempotent upsert)."""
    permission_model = apps.get_model("accounts", "Permission")
    for perm in PERMISSIONS:
        if perm.code not in _CATALOG_CODES:
            continue
        permission_model.objects.update_or_create(
            code=perm.code,
            defaults={"module": perm.module, "name": perm.name, "is_sensitive": perm.sensitive},
        )


def unseed_catalog_permissions(apps: "Apps", schema_editor: "BaseDatabaseSchemaEditor") -> None:
    permission_model = apps.get_model("accounts", "Permission")
    permission_model.objects.filter(code__in=_CATALOG_CODES).delete()


